// Deterministic check for Google Antigravity (`hosts/antigravity/ia`) and
// Gemini CLI (`hosts/gemini/ia`) host bundles generated by `tools/build-host-plugins.mjs`.
import assert from 'node:assert/strict';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { buildHostPlugins } from '../tools/build-host-plugins.mjs';

const ROOT = fileURLToPath(new URL('../', import.meta.url));
const readJson = rel => JSON.parse(readFileSync(join(ROOT, rel), 'utf8'));

test('checked-in Antigravity and Gemini CLI host bundles match tools/build-host-plugins.mjs byte-for-byte', () => {
  const result = buildHostPlugins(ROOT, { write: false });
  assert.deepEqual(result, {
    ok: true,
    files: result.files,
    missing: [],
    extra: [],
    drifted: [],
  });
  assert.ok(result.files > 100);
});

test('Antigravity bundle obeys plugin.json, mcp_config.json, flat/grouped hooks.json, rules, and subagent contracts', () => {
  const claude = readJson('plugins/ia/.claude-plugin/plugin.json');
  const discovery = readJson('.agents/plugins.json');
  assert.deepEqual(discovery, { entries: [{ path: 'hosts/antigravity' }] });

  const manifest = readJson('hosts/antigravity/ia/plugin.json');
  const allowedKeys = new Set([
    'name', 'displayName', 'version', 'description', 'author',
    'homepage', 'repository', 'logo', 'suggestedPrompts', 'disabled',
  ]);
  for (const key of Object.keys(manifest)) {
    assert.ok(allowedKeys.has(key), `unexpected plugin.json key: ${key}`);
  }
  assert.equal(manifest.name, 'ia');
  assert.equal(manifest.version, claude.version);
  assert.ok(existsSync(join(ROOT, 'hosts/antigravity/ia', manifest.logo)));

  const mcp = readJson('hosts/antigravity/ia/mcp_config.json');
  assert.deepEqual(Object.keys(mcp.mcpServers).sort(), ['ia', 'inventarch']);
  assert.equal(mcp.mcpServers.ia.command, 'node');
  assert.equal(mcp.mcpServers.inventarch.url, 'https://api.inventarch.dev/mcp');
  assert.equal(mcp.variables, undefined, 'no setup variables that would ship the plugin disabled');

  const hooks = readJson('hosts/antigravity/ia/hooks.json')['ia-core'];
  // SessionStart, PreInvocation, PostInvocation and Stop are flat handler arrays;
  // PreToolUse and PostToolUse are matcher-grouped handler arrays.
  for (const flat of ['SessionStart', 'PreInvocation', 'PostInvocation', 'Stop']) {
    assert.ok(Array.isArray(hooks[flat]) && hooks[flat].length === 1, `${flat} must be a flat array`);
    assert.equal(hooks[flat][0].type, 'command');
    assert.equal(hooks[flat][0].matcher, undefined, `${flat} does not use matcher groups`);
  }
  for (const grouped of ['PreToolUse', 'PostToolUse']) {
    assert.ok(Array.isArray(hooks[grouped]) && hooks[grouped].length === 1, `${grouped} must be grouped`);
    assert.equal(typeof hooks[grouped][0].matcher, 'string');
    assert.ok(Array.isArray(hooks[grouped][0].hooks) && hooks[grouped][0].hooks.length === 1);
  }

  const rulesText = readFileSync(join(ROOT, 'hosts/antigravity/ia/rules/AGENTS.md'), 'utf8');
  assert.match(rulesText, /^---\ntrigger: always_on\n---\n/);

  for (const skill of readdirSync(join(ROOT, 'hosts/antigravity/ia/skills'))) {
    const text = readFileSync(join(ROOT, 'hosts/antigravity/ia/skills', skill, 'SKILL.md'), 'utf8');
    assert.match(text, /\*\*Antigravity:\*\* read \[the Antigravity host instructions\]\(\.\.\/\.\.\/rules\/AGENTS\.md\) first\./);
    assert.doesNotMatch(text, /\.\.\/\.\.\/CODEX\.md/);
  }

  for (const agentFile of readdirSync(join(ROOT, 'hosts/antigravity/ia/agents'))) {
    const text = readFileSync(join(ROOT, 'hosts/antigravity/ia/agents', agentFile), 'utf8');
    assert.match(text, /^---\n[\s\S]*?\nsubagent: true\nmainAgent: false\ntools: \[[^\]]+\]\n---\n/);
    assert.doesNotMatch(text, /^model:/m);
    assert.doesNotMatch(text, /^maxTurns:/m);
  }
});

test('Gemini CLI bundle obeys gemini-extension.json, millisecond hooks/hooks.json, GEMINI.md, and agent tool names', () => {
  const claude = readJson('plugins/ia/.claude-plugin/plugin.json');
  const ext = readJson('hosts/gemini/ia/gemini-extension.json');
  assert.equal(ext.name, 'ia');
  assert.equal(ext.version, claude.version);
  assert.equal(ext.contextFileName, 'GEMINI.md');
  assert.deepEqual(Object.keys(ext.mcpServers).sort(), ['ia', 'inventarch']);
  assert.deepEqual(ext.mcpServers.inventarch, {
    httpUrl: 'https://api.inventarch.dev/mcp',
    oauth: { enabled: true, clientId: 'gemini-cli' },
  });

  const hooks = readJson('hosts/gemini/ia/hooks/hooks.json').hooks;
  for (const event of ['SessionStart', 'BeforeAgent', 'BeforeTool', 'AfterTool', 'AfterAgent']) {
    assert.ok(Array.isArray(hooks[event]) && hooks[event].length === 1, `missing ${event}`);
    const inner = hooks[event][0].hooks[0];
    assert.equal(inner.type, 'command');
    assert.ok(inner.timeout >= 1000, `${event} timeout must be in milliseconds`);
    assert.match(inner.command, /\$\{extensionPath\}\/scripts\/gemini-hook\.mjs/);
  }

  for (const skill of readdirSync(join(ROOT, 'hosts/gemini/ia/skills'))) {
    const text = readFileSync(join(ROOT, 'hosts/gemini/ia/skills', skill, 'SKILL.md'), 'utf8');
    assert.match(text, /\*\*Gemini CLI:\*\* read \[the Gemini CLI host instructions\]\(\.\.\/\.\.\/GEMINI\.md\) first\./);
    assert.doesNotMatch(text, /\.\.\/\.\.\/CODEX\.md/);
  }

  for (const agentFile of readdirSync(join(ROOT, 'hosts/gemini/ia/agents'))) {
    const text = readFileSync(join(ROOT, 'hosts/gemini/ia/agents', agentFile), 'utf8');
    assert.match(text, /^---\nname: "[^"]+"\ndescription: "[^"]+"\ntools: \[[^\]]+\]\n---\n/);
  }
});
